* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, sans-serif; font-size: 16px; background: #172b3a; color: #f4f0df; }
body { min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background-image: linear-gradient(30deg, #203847 12%, transparent 12.5%, transparent 87%, #203847 87.5%, #203847), linear-gradient(150deg, #203847 12%, transparent 12.5%, transparent 87%, #203847 87.5%, #203847); background-size: 34px 58px; }
.board { width: min(100%, 500px); padding: clamp(22px, 6vw, 36px); background: #263e4b; border: 4px solid #4c6870; box-shadow: 8px 8px 0 #101e29; }
.heading { display: flex; align-items: center; gap: 16px; padding-bottom: 24px; border-bottom: 2px dashed #4c6870; }
.pixel-icon { display: grid; place-items: center; width: 54px; height: 54px; background: #f1b84b; color: #172b3a; font-size: 28px; }
.eyebrow { margin: 0 0 4px; color: #a8c8bd; font-size: 0.8rem; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(1.6rem, 6vw, 2rem); }
fieldset { min-width: 0; margin: 24px 0; padding: 0; border: 0; }
legend { margin-bottom: 14px; font-weight: 700; }
.time-fields { display: flex; align-items: end; gap: 12px; }
.time-fields label, .label-field { display: grid; gap: 8px; font-weight: 600; }
.time-fields input { width: 92px; text-align: center; }
input { min-height: 48px; padding: 10px 12px; border: 2px solid #4c6870; border-radius: 2px; background: #172b3a; color: #f4f0df; font: inherit; }
input::placeholder { color: #a8c8bd; opacity: .75; }
input:focus-visible, button:focus-visible { outline: 3px solid #f1b84b; outline-offset: 3px; }
.colon { padding-bottom: 10px; font-size: 1.5rem; }
.label-field { margin-top: 16px; }
.optional { color: #a8c8bd; font-weight: 400; }
.add-button { width: 100%; min-height: 50px; margin-top: 18px; border: 0; background: #f1b84b; color: #172b3a; font: inherit; font-weight: 800; cursor: pointer; }
button { transition: filter .12s, transform .12s; }
button:hover { filter: brightness(1.1); }
button:active { transform: translateY(2px); }
.list-heading { display: flex; align-items: center; justify-content: space-between; border-top: 2px dashed #4c6870; padding-top: 20px; }
h2 { margin: 0; font-size: 1.15rem; }
.count { padding: 5px 10px; background: #a8c8bd; color: #172b3a; font-weight: 800; }
.alarm-list { display: grid; gap: 10px; margin: 16px 0 0; padding: 0; list-style: none; }
.alarm-row { display: flex; align-items: center; gap: 12px; padding: 13px; background: #1d3341; border-left: 4px solid #a8c8bd; }
.alarm-row.off { border-left-color: #4c6870; opacity: .65; }
.alarm-time { min-width: 78px; font-size: 1.35rem; font-weight: 800; font-variant-numeric: tabular-nums; }
.alarm-name { flex: 1; min-width: 0; overflow-wrap: anywhere; color: #a8c8bd; }
.alarm-row button { min-height: 42px; padding: 8px 10px; border: 2px solid #4c6870; background: transparent; color: #f4f0df; font: inherit; cursor: pointer; }
.alarm-row button[aria-pressed="true"] { border-color: #a8c8bd; color: #a8c8bd; }
.alarm-row .delete-button { border-color: transparent; color: #f1b84b; }
.empty-message { color: #a8c8bd; text-align: center; padding: 18px 0; }
footer { margin-top: 26px; padding-top: 16px; border-top: 2px dashed #4c6870; color: #a8c8bd; font-size: .75rem; letter-spacing: .1em; text-align: center; }
footer span { margin-left: 8px; color: #f1b84b; }
@media (max-width: 390px) { .alarm-row { gap: 7px; padding: 10px 8px; } .alarm-row button { padding-inline: 7px; } .alarm-time { min-width: 70px; } }

const form = document.querySelector('#alarm-form');
const hourInput = document.querySelector('#hour');
const minuteInput = document.querySelector('#minute');
const labelInput = document.querySelector('#label');
const list = document.querySelector('#alarm-list');
const count = document.querySelector('#on-count');
const emptyMessage = document.querySelector('#empty-message');
let alarms = [];
let nextId = 1;

function render() {
  alarms.sort((a, b) => a.hour * 60 + a.minute - (b.hour * 60 + b.minute));
  list.replaceChildren();
  for (const alarm of alarms) {
    const row = document.createElement('li');
    row.className = `alarm-row${alarm.enabled ? '' : ' off'}`;
    const time = document.createElement('span');
    time.className = 'alarm-time';
    time.textContent = `${String(alarm.hour).padStart(2, '0')}:${String(alarm.minute).padStart(2, '0')}`;
    const name = document.createElement('span');
    name.className = 'alarm-name';
    name.textContent = alarm.label || 'Alarm';
    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.textContent = alarm.enabled ? 'On' : 'Off';
    toggle.setAttribute('aria-pressed', String(alarm.enabled));
    toggle.setAttribute('aria-label', `${alarm.enabled ? 'Turn off' : 'Turn on'} alarm at ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''}`);
    toggle.addEventListener('click', () => {
      alarm.enabled = !alarm.enabled;
      render();
    });
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.textContent = 'Delete';
    remove.setAttribute('aria-label', `Delete alarm at ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''}`);
    remove.addEventListener('click', () => {
      alarms = alarms.filter(item => item.id !== alarm.id);
      render();
    });
    row.append(time, name, toggle, remove);
    list.append(row);
  }
  const enabled = alarms.filter(alarm => alarm.enabled).length;
  count.textContent = `${enabled} on`;
  emptyMessage.hidden = alarms.length > 0;
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const hour = Number(hourInput.value);
  const minute = Number(minuteInput.value);
  if (!Number.isInteger(hour) || hour < 0 || hour > 23 || !Number.isInteger(minute) || minute < 0 || minute > 59) return;
  alarms.push({ id: nextId++, hour, minute, label: labelInput.value.trim(), enabled: true });
  form.reset();
  hourInput.focus();
  render();
});

render();
